-- PT119-S3-Q12. Batch 09.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch09$PT119-S3-Q12$batch09$ AND q.stimulus=$batch09$Our computer experts are asked from time to time to allocate funds for new hardware and software for our company. Unfortunately, these experts favor cutting-edge technologies, because that is what excites them, despite the fact that such experimental technologies are highly expensive, full of undiscovered “bugs,” and thus are not the most profitable investments.$batch09$ AND q.prompt=$batch09$Of the following, which one conforms most closely to the principle illustrated by the situation described above?$batch09$ AND q.correct_choice=$batch09$C$batch09$) THEN RAISE EXCEPTION 'Question changed: PT119-S3-Q12'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch09$PT119-S3-Q12$batch09$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT119-S3-Q12'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch09$PT119-S3-Q12$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch09$Situation$batch09$, $batch09$The company's computer experts choose technology that excites them, even though those choices are expensive, buggy and not the most profitable for the company.$batch09$), (1, $batch09$Evaluate$batch09$, $batch09$The experts are choosing for an organization, and they choose by personal taste instead of by what serves the organization. Both halves have to be there. Someone choosing for a group, and personal enjoyment beating the group's interest.$batch09$), (2, $batch09$Goal$batch09$, $batch09$People who choose for an organization pick what they personally enjoy, not what best serves the organization.$batch09$)) v(position,label,body) WHERE q.qid=$batch09$PT119-S3-Q12$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch09$A$batch09$, $batch09$This is the trap, picked by 7%. Executives favoring people who share their interests looks like personal taste. But the alternative they pass over is "the most education." Nothing says education is what serves the company best. The stimulus contrasts personal taste with the organization's interest, and A contrasts it with education.$batch09$), ($batch09$B$batch09$, $batch09$Supermarkets choose for profit. That's choosing in the organization's interest, which the experts failed to do.$batch09$), ($batch09$C$batch09$, $batch09$Librarians choose for the library, they pick books they enjoy, and they pass over books that serve the community the library is for. Personal taste beats the interest of those they choose for.$batch09$), ($batch09$D$batch09$, $batch09$Students choosing their own courses are choosing for themselves. Picking easy courses is a personal tradeoff, not a betrayal of an organization's interest.$batch09$), ($batch09$E$batch09$, $batch09$The executives pick what viewers want, which serves the network's audience. They aren't indulging their own taste.$batch09$)) v(letter,body) WHERE q.qid=$batch09$PT119-S3-Q12$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
